<div class="page-heading"><div><span class="eyebrow">KNOW WHAT HAPPENED</span><h1>Security activity</h1><p>Recent actions associated with your account.</p></div><span class="session-indicator"><span></span> Account protected</span></div><section class="card activity-card"><div class="section-heading"><div><h2>Your activity timeline</h2><p>The latest 50 events. Times are shown in UTC.</p></div><span class="stat-icon green"><?= icon('shield') ?></span></div><?php foreach ($events as $event): ?><div class="activity-row"><span class="activity-dot"><?= icon(str_contains($event['event_type'], 'document') ? 'file' : 'shield') ?></span><div><h3><?= e(ucwords(str_replace('_', ' ', $event['event_type']))) ?></h3><p><?= e($event['description']) ?></p></div><time><?= e($event['created_at']) ?> UTC</time></div><?php endforeach; ?><?php if (!$events): ?><div class="empty-state"><p>No activity to show yet.</p></div><?php endif; ?></section><p class="privacy-note"><?= icon('lock') ?> Passwords, document contents, and session tokens are never written to this activity log.</p>
<?php page_end(); ?>
